ST.xhtml:
(* ---- program identity (scenario = cylinder_seq) ---- *)
prog_id := 5;

(* ---- stop / emergency: leave auto cycle, both cylinders driven home ---- *)
IF stop_btn THEN
    running := FALSE;
END_IF;

IF NOT running THEN
    a_fwd := FALSE; a_bwd := TRUE;
    b_fwd := FALSE; b_bwd := TRUE;
    step_no := 0;
    (* start only from home position: both retracted *)
    IF start_btn AND a_ret AND b_ret THEN
        running := TRUE;
        step_no := 1;
    END_IF;
ELSE
    (* ---- sequence: 1 A-extend, 2 B-extend, 3 B-retract, 4 A-retract, loop ---- *)
    CASE step_no OF
        1:
            a_fwd := TRUE;  a_bwd := FALSE;
            b_fwd := FALSE; b_bwd := TRUE;
            IF a_ext THEN step_no := 2; END_IF;
        2:
            a_fwd := TRUE;  a_bwd := FALSE;
            b_fwd := TRUE;  b_bwd := FALSE;
            IF b_ext THEN step_no := 3; END_IF;
        3:
            a_fwd := TRUE;  a_bwd := FALSE;
            b_fwd := FALSE; b_bwd := TRUE;
            IF b_ret THEN step_no := 4; END_IF;
        4:
            a_fwd := FALSE; a_bwd := TRUE;
            b_fwd := FALSE; b_bwd := TRUE;
            IF a_ret THEN step_no := 1; END_IF;
    END_CASE;
END_IF;
